const $ = id => document.getElementById(id);
const config = window.NOI_CONFIG;
let user=null, auth, db, fs, au, stopUsers, stopCalls, heartbeat, api, people=[];
const toast = message => { $('toast').textContent=message; $('toast').style.display='block'; clearTimeout(toast.timer); toast.timer=setTimeout(()=>$('toast').style.display='none',5500); };
const error = e => toast(`Không thể thực hiện: ${e.code || e.message || 'Vui lòng thử lại'}`);
const authDialog = () => { $('authHint').textContent=config.firebase ? 'Sử dụng tài khoản của bạn để tiếp tục.' : 'Đăng nhập hiện chưa sẵn sàng. Vui lòng liên hệ quản trị viên.'; $('authDialog').showModal(); };
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('teamName').textContent=config.teamName || 'Nhóm của chúng tôi';
if(config.members?.length) $('members').textContent=config.members.join('\n');
$('loginTop').onclick=authDialog;
$('loginGateButton').onclick=authDialog;
function renderAccess(){const signedIn=Boolean(auth?.currentUser && user && auth.currentUser.uid===user.uid);document.querySelectorAll('[data-auth]').forEach(element=>{element.hidden=!signedIn;});$('loginGate').hidden=signedIn;if(!signedIn){document.querySelectorAll('dialog[data-invitation]').forEach(dialog=>dialog.close());$('room').value='';$('search').value='';}} 
function renderPeople(){const list=$('peopleList');list.replaceChildren();$('count').textContent=people.length;const filtered=people.filter(p=>p.name.toLocaleLowerCase('vi').includes($('search').value.toLocaleLowerCase('vi')));if(!filtered.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=!user?'Đăng nhập để xem mọi người và bắt đầu kết nối.':people.length?'Không tìm thấy người dùng phù hợp.':'Chưa có người dùng khác. Mời bạn bè đăng nhập để cùng kết nối.';list.append(empty);return;}for(const person of filtered){const card=document.createElement('article');card.className='person';const av=document.createElement('div');av.className='avatar';av.textContent=person.name.slice(0,1).toUpperCase();const info=document.createElement('div'),name=document.createElement('b'),status=document.createElement('p');name.textContent=person.name;status.textContent=person.lastSeen && Date.now()-person.lastSeen.toMillis()<90000?'● Đang hoạt động':'Chưa hoạt động gần đây';info.append(name,status);const call=document.createElement('button');call.textContent='↗';call.setAttribute('aria-label',`Gọi ${person.name}`);call.onclick=()=>invite(person);card.append(av,info,call);list.append(card);}}
$('search').oninput=renderPeople;
function cleanup(){stopUsers?.();stopCalls?.();clearInterval(heartbeat);people=[];}
function renderAccount(){renderAccess();const account=$('account');account.replaceChildren();if(!user){const b=document.createElement('button');b.textContent='Đăng nhập ↗';b.onclick=authDialog;account.append(b);}else{const name=document.createElement('span');name.textContent=(user.displayName||'Thành viên');const out=document.createElement('button');out.textContent='Đăng xuất';out.onclick=async()=>{try{await au.signOut(auth);}catch(e){error(e);}};account.append(name,out);}}
async function login(provider){if(!auth)return toast('Đăng nhập hiện chưa sẵn sàng. Vui lòng liên hệ quản trị viên.');try{await au.signInWithPopup(auth,provider==='google'?new au.GoogleAuthProvider():new au.GithubAuthProvider());$('authDialog').close();}catch(e){error(e);}}
$('google').onclick=()=>login('google');$('github').onclick=()=>login('github');
function canCall(){if(!auth?.currentUser || !user || auth.currentUser.uid!==user.uid){authDialog();return false;}return true;}
const newRoom=()=>`noi-${crypto.randomUUID()}`;
$('create').onclick=()=>{if(canCall()) startCall(newRoom());};
$('join').onsubmit=e=>{e.preventDefault();if(canCall())startCall($('room').value.trim());};
async function invite(person){if(!canCall())return;const room=newRoom();try{await fs.addDoc(fs.collection(db,'calls'),{from:user.uid,to:person.uid,room,createdAt:fs.serverTimestamp()});await startCall(room);}catch(e){error(e);}}
let jitsiPromise;
function loadJitsi(){if(window.JitsiMeetExternalAPI)return Promise.resolve();if(jitsiPromise)return jitsiPromise;jitsiPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://meet.jit.si/external_api.js';const timeout=setTimeout(()=>{script.remove();jitsiPromise=null;reject(new Error('Tải dịch vụ video quá lâu. Hãy thử lại.'));},20000);script.onload=()=>{clearTimeout(timeout);resolve();};script.onerror=()=>{clearTimeout(timeout);script.remove();jitsiPromise=null;reject(new Error('Không tải được dịch vụ Jitsi.'));};document.head.append(script);});return jitsiPromise;}
async function startCall(room){if(!canCall())return;if(!/^[a-zA-Z0-9-]{6,100}$/.test(room))return toast('Mã phòng cần 6–100 ký tự, chỉ gồm chữ, số và dấu gạch ngang.');if($('callDialog').open)return toast('Hãy rời phòng hiện tại trước.');$('callTitle').textContent=room;$('meeting').textContent='Đang kết nối dịch vụ video…';$('callDialog').showModal();try{await loadJitsi();if(!$('callDialog').open)return;$('meeting').replaceChildren();api=new window.JitsiMeetExternalAPI('meet.jit.si',{roomName:room,width:'100%',height:'100%',parentNode:$('meeting'),userInfo:{displayName:user.displayName||'Thành viên'},configOverwrite:{prejoinConfig:{enabled:true},startWithAudioMuted:true}});api.addEventListener('readyToClose',leave);const url=new URL(location.href);url.searchParams.set('room',room);history.replaceState(null,'',url);}catch(e){leave();error(e);}}
function leave(){api?.dispose();api=null;$('callDialog').close();$('meeting').replaceChildren();const url=new URL(location.href);url.searchParams.delete('room');history.replaceState(null,'',url);}
$('leave').onclick=leave;$('callDialog').addEventListener('cancel',e=>{e.preventDefault();leave();});
$('copy').onclick=async()=>{try{const url=new URL(location.href);url.searchParams.set('room',$('callTitle').textContent);await navigator.clipboard.writeText(url.href);toast('Đã sao chép liên kết mời.');}catch{toast('Không sao chép được. Bạn có thể sao chép địa chỉ trên trình duyệt.');}};
renderAccess();
renderPeople();
async function boot(){if(!config.firebase)return;try{const base='https://www.gstatic.com/firebasejs/11.10.0/';const [app,authModule,firestore]=await Promise.all([import(base+'firebase-app.js'),import(base+'firebase-auth.js'),import(base+'firebase-firestore.js')]);au=authModule;fs=firestore;const instance=app.initializeApp(config.firebase);auth=au.getAuth(instance);auth.languageCode='vi';db=fs.getFirestore(instance);au.onAuthStateChanged(auth,async current=>{cleanup();user=current;renderAccount();renderPeople();if(!current){if($('callDialog').open)leave();return;}const update=()=>fs.setDoc(fs.doc(db,'users',current.uid),{name:current.displayName||'Thành viên',lastSeen:fs.serverTimestamp()});try{await update();heartbeat=setInterval(()=>update().catch(error),30000);stopUsers=fs.onSnapshot(fs.collection(db,'users'),snap=>{people=snap.docs.filter(d=>d.id!==current.uid).map(d=>({uid:d.id,...d.data()})).sort((a,b)=>a.name.localeCompare(b.name,'vi'));renderPeople();},error);const since=Date.now();const handled=new Set();stopCalls=fs.onSnapshot(fs.query(fs.collection(db,'calls'),fs.where('to','==',current.uid)),snap=>{for(const change of snap.docChanges()){const call=change.doc.data();if(change.type!=='added'||handled.has(change.doc.id)||!call.createdAt||call.createdAt.toMillis()<since-1000)continue;handled.add(change.doc.id);const caller=people.find(p=>p.uid===call.from)?.name||'Một thành viên';showInvitation(caller,call.room);}},error);const room=new URL(location.href).searchParams.get('room');if(room)startCall(room);}catch(e){error(e);}});}catch(e){error(e);}}
function showInvitation(name,room){if(!auth?.currentUser)return;if($('callDialog').open)return toast(`${name} đang gọi. Bạn đang ở trong một phòng khác.`);const dialog=document.createElement('dialog');dialog.dataset.invitation='';const title=document.createElement('h2');title.textContent=`${name} đang mời bạn gọi video`;const accept=document.createElement('button');accept.className='primary';accept.textContent='Tham gia';const decline=document.createElement('button');decline.textContent='Để sau';accept.onclick=()=>{dialog.close();startCall(room);};decline.onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.append(title,accept,decline);document.body.append(dialog);dialog.showModal();}
boot();
